// trigger/lib/llm.ts
// LLM helper for Trigger.dev tasks - supports Groq (Llama) and OpenAI
//
// MODEL STRATEGY (Nov 2025):
// - GPT-5 Nano: Intensive tasks (final packs, knowledge graph) - best quality
// - Groq Llama 3.1 8B: Everything else - fast & free

import { logger } from "@trigger.dev/sdk";

export interface ChatMessage {
  role: "system" | "user" | "assistant";
  content: string;
}

export interface LLMOptions {
  temperature?: number;
  maxTokens?: number;
  model?: string;
  /** Use GPT-5 Nano for intensive/quality-critical tasks */
  intensive?: boolean;
}

/**
 * Call Groq API with Llama 3.1 8B (SLM for cost efficiency)
 * Used for knowledge extraction and educational content generation
 */
export async function callGroqSLM(
  messages: ChatMessage[],
  opts: LLMOptions = {}
): Promise<string> {
  const apiKey = process.env.GROQ_API_KEY;
  if (!apiKey) {
    throw new Error("GROQ_API_KEY not configured");
  }

  const { temperature = 0.2, maxTokens = 4096, model = "llama-3.1-8b-instant" } = opts;

  const response = await fetch("https://api.groq.com/openai/v1/chat/completions", {
    method: "POST",
    headers: {
      Authorization: `Bearer ${apiKey}`,
      "Content-Type": "application/json",
    },
    body: JSON.stringify({
      model,
      messages,
      temperature,
      max_tokens: maxTokens,
      response_format: { type: "json_object" },
    }),
  });

  if (!response.ok) {
    const err = await response.text();
    logger.error("Groq API error", { status: response.status, error: err });
    throw new Error(`Groq API error: ${err}`);
  }

  const data = await response.json() as { choices: Array<{ message: { content: string } }> };
  return data.choices[0].message.content;
}

/**
 * Call OpenAI API with GPT-5 Nano (default)
 * GPT-5 Nano: $0.05/1M in, $0.40/1M out - Best quality for cost
 * Note: GPT-5 Nano only supports temperature=1 and uses max_completion_tokens
 */
export async function callOpenAI(
  messages: ChatMessage[],
  opts: LLMOptions = {}
): Promise<string> {
  const apiKey = process.env.OPENAI_API_KEY;
  if (!apiKey) {
    throw new Error("OPENAI_API_KEY not configured");
  }

  const { temperature = 0.2, maxTokens = 4096, model = "gpt-5-nano" } = opts;

  // GPT-5 Nano has different API requirements
  const isGpt5Nano = model === "gpt-5-nano";
  
  const response = await fetch("https://api.openai.com/v1/chat/completions", {
    method: "POST",
    headers: {
      Authorization: `Bearer ${apiKey}`,
      "Content-Type": "application/json",
    },
    body: JSON.stringify({
      model,
      messages,
      // GPT-5 Nano only supports temperature=1 (default), so omit for that model
      ...(!isGpt5Nano && { temperature }),
      // GPT-5 Nano uses max_completion_tokens, older models use max_tokens
      ...(isGpt5Nano ? { max_completion_tokens: maxTokens } : { max_tokens: maxTokens }),
    }),
  });

  if (!response.ok) {
    const err = await response.text();
    logger.error("OpenAI API error", { status: response.status, error: err });
    throw new Error(`OpenAI API error: ${err}`);
  }

  const data = await response.json() as { choices: Array<{ message: { content: string } }> };
  return data.choices[0].message.content;
}

/**
 * Primary LLM call function
 * 
 * MODEL STRATEGY (Nov 2025):
 * - GPT-5 Nano: Intensive tasks (final packs, knowledge graph) - best quality
 * - Groq Llama 3.1 8B: Everything else - fast & free
 * 
 * Use `intensive: true` for quality-critical tasks that need GPT-5 Nano
 */
export async function callLLM(
  messages: ChatMessage[],
  opts: LLMOptions = {}
): Promise<string> {
  const { intensive = false, ...llmOpts } = opts;
  
  // INTENSIVE TASKS: Use GPT-5 Nano for best quality
  if (intensive && process.env.OPENAI_API_KEY) {
    logger.info("Using GPT-5 Nano for intensive task");
    return await callOpenAI(messages, llmOpts);
  }
  
  // STANDARD TASKS: Use Groq Llama 3.1 8B - fast & free
  if (process.env.GROQ_API_KEY) {
    try {
      return await callGroqSLM(messages, llmOpts);
    } catch (error) {
      // If Groq fails (rate limit, etc.), fall back to GPT-5 Nano
      if (process.env.OPENAI_API_KEY) {
        logger.warn("Groq rate limited, falling back to GPT-5 Nano", { error });
        return await callOpenAI(messages, llmOpts);
      }
      throw error;
    }
  }
  
  // Last resort: GPT-5 Nano if no Groq key
  if (process.env.OPENAI_API_KEY) {
    return await callOpenAI(messages, llmOpts);
  }
  
  throw new Error("No LLM API key configured (GROQ_API_KEY or OPENAI_API_KEY required)");
}

